export function PricingTier({
  planName = "{{planName}}",
  price = {{price}},
  ctaText = "{{ctaText}}",
  highlighted = {{highlighted}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "15px system-ui, sans-serif", color: "#241430", maxWidth: 240, padding: 24, borderRadius: 16,
      border: `1.5px solid ${highlighted ? accent : "#24143022"}`, background: "#FAF7F2", position: "relative",
      boxShadow: highlighted ? "0 16px 32px rgba(36,20,48,.14)" : "none" }}>
      {highlighted && (
        <span style={{ position: "absolute", top: -12, left: 24, background: accent, color: "#FAF7F2", fontSize: 11,
          fontWeight: 700, padding: "4px 10px", borderRadius: 999 }}>Most popular</span>
      )}
      <p style={{ margin: "0 0 6px", fontWeight: 700, textTransform: "uppercase", fontSize: 12, letterSpacing: "0.05em", color: "#241430aa" }}>{planName}</p>
      <p style={{ margin: "0 0 18px", fontSize: 34, fontWeight: 800 }}>
        <span style={{ fontSize: 20, verticalAlign: "top" }}>$</span>{price}<small style={{ fontSize: 14, fontWeight: 500, color: "#241430aa" }}>/mo</small>
      </p>
      <ul style={{ listStyle: "none", margin: "0 0 20px", padding: 0, display: "flex", flexDirection: "column", gap: 8, fontSize: 14, color: "#241430cc" }}>
        <li>&#10003; Unlimited projects</li>
        <li>&#10003; Priority support</li>
        <li>&#10003; Team analytics</li>
      </ul>
      <button type="button" style={{ width: "100%", border: `1.5px solid ${accent}`,
        background: highlighted ? accent : "transparent", color: highlighted ? "#FAF7F2" : accent,
        padding: 10, borderRadius: 8, fontWeight: 700, cursor: "pointer" }}>{ctaText}</button>
    </div>
  );
}
